const PRODUCTOS_FALLBACK = [{"n":"MEDIA TARTA ATUN","c":"Tartas","s":"Media Tarta","p":12500},{"n":"MEDIA TARTA CAPRECCE","c":"Tartas","s":"Media Tarta","p":11500},{"n":"MEDIA TARTA CEBOLLA","c":"Tartas","s":"Media Tarta","p":11000},{"n":"MEDIA TARTA CHOCLO","c":"Tartas","s":"Media Tarta","p":11500},{"n":"MEDIA TARTA DE BROCOLI Y CALABZA","c":"Tartas","s":"Media Tarta","p":11500},{"n":"MEDIA TARTA ESPINACA","c":"Tartas","s":"Media Tarta","p":11500},{"n":"MEDIA TARTA JAMON Y QUESO","c":"Tartas","s":"Media Tarta","p":10500},{"n":"MEDIA TARTA POLLO","c":"Tartas","s":"Media Tarta","p":12500},{"n":"MEDIA TARTA VEGETALES","c":"Tartas","s":"Media Tarta","p":11500},{"n":"MEDIA TARTA VERDURA","c":"Tartas","s":"Media Tarta","p":10000},{"n":"MEDIA TARTA ZAPALLITOS","c":"Tartas","s":"Media Tarta","p":11000},{"n":"TARTA ATUN","c":"Tartas","s":"Tarta Grande","p":20500},{"n":"TARTA CAPRECCE","c":"Tartas","s":"Tarta Grande","p":19000},{"n":"TARTA CEBOLLA Y QUESO","c":"Tartas","s":"Tarta Grande","p":18000},{"n":"TARTA CHOCLO","c":"Tartas","s":"Tarta Grande","p":19000},{"n":"TARTA DE BROCOLI Y CALABAZA","c":"Tartas","s":"Tarta Grande","p":19000},{"n":"TARTA ESPINACA","c":"Tartas","s":"Tarta Grande","p":19000},{"n":"TARTA JAMON Y QUESO","c":"Tartas","s":"Tarta Grande","p":18000},{"n":"TARTA POLLO","c":"Tartas","s":"Tarta Grande","p":20500},{"n":"TARTA VERDURA","c":"Tartas","s":"Tarta Grande","p":17000},{"n":"TARTA VERGETALES MIXTOS","c":"Tartas","s":"Tarta Grande","p":19000},{"n":"TARTA ZAPALLITOS","c":"Tartas","s":"Tarta Grande","p":18000},{"n":"TARTELETA VERDURA","c":"Tartas","s":"Tartelleta","p":8500},{"n":"TARTELLETA ATUN","c":"Tartas","s":"Tartelleta","p":10000},{"n":"TARTELLETA CAPRECCE","c":"Tartas","s":"Tartelleta","p":9500},{"n":"TARTELLETA CEBOLLA Y QUESO","c":"Tartas","s":"Tartelleta","p":8500},{"n":"TARTELLETA CHOCLO","c":"Tartas","s":"Tartelleta","p":9500},{"n":"TARTELLETA DE BROCOLI Y CALABAZA","c":"Tartas","s":"Tartelleta","p":9500},{"n":"TARTELLETA ESPINACA","c":"Tartas","s":"Tartelleta","p":9500},{"n":"TARTELLETA JAMON Y QUESO","c":"Tartas","s":"Tartelleta","p":8500},{"n":"TARTELLETA POLLO","c":"Tartas","s":"Tartelleta","p":10000},{"n":"TARTELLETA VEGETALES","c":"Tartas","s":"Tartelleta","p":9500},{"n":"TARTELLETA ZAPALLITOS","c":"Tartas","s":"Tartelleta","p":8500}];
let PRODUCTOS = PRODUCTOS_FALLBACK;

const IMG_TARTA_ENTERA = 'data:image/jpeg;base64,';
const IMG_MEDIA_TARTA = 'data:image/jpeg;base64,';
const IMG_TARTELLETA = 'data:image/jpeg;base64,';

let carrito = [];
let tipoPedido = 'envio';
let pedidoConfirmado = null;

function fmt(n){ return '$'+n.toLocaleString('es-AR'); }

// ─── SUPABASE ────────────────────────────────────────────────
async function sbFetch(path, opts={}) {
  const { prefer, headers: extraHeaders, ...rest } = opts;
  const res = await fetch(SUPA_URL + path, {
    headers: {
      'apikey': SUPA_KEY, 'Authorization': 'Bearer ' + SUPA_KEY,
      'Content-Type': 'application/json', 'Prefer': prefer || '',
      ...(extraHeaders||{})
    }, ...rest
  });
  if (!res.ok && res.status !== 204) throw new Error(await res.text());
  if (res.status === 204) return null;
  return res.json();
}

// ─── CARGA DE PRODUCTOS EN VIVO (misma fuente que el panel Admin) ─
async function cargarProductosTartas() {
  try {
    const data = await sbFetch("/rest/v1/productos?select=nombre,categoria,subcategoria,precio&categoria=eq.Tartas&subcategoria=in.(Tarta%20Grande,Media%20Tarta,Tartelleta)&activo=eq.true&order=nombre");
    if (data && data.length > 0) {
      PRODUCTOS = data
        .filter(p => !/^ADICIONAL/i.test(p.nombre.trim())) // excluir productos internos tipo "ADICIONAL 1/2 TARTA"
        .map(p => ({ n: p.nombre, c: p.categoria, s: p.subcategoria, p: p.precio }));
    }
  } catch(e) {
    // Si falla la conexión, seguimos con PRODUCTOS_FALLBACK ya asignado
    console.warn('No se pudo cargar precios en vivo, usando respaldo local:', e.message);
  }
}

// ─── RENDER CATÁLOGO ───────────────────────────────────────────
function imgFor(subcat) {
  if (subcat === 'Tarta Grande') return IMG_TARTA_ENTERA;
  if (subcat === 'Media Tarta') return IMG_MEDIA_TARTA;
  if (subcat === 'Tartelleta') return IMG_TARTELLETA;
  return IMG_TARTA_ENTERA;
}

const CATEGORIAS = [
  {subcat:'Tarta Grande', nombre:'Tarta grande', desc:'Entera, para compartir'},
  {subcat:'Media Tarta', nombre:'Media tarta', desc:'Porcion para dos'},
  {subcat:'Tartelleta', nombre:'Tartelleta', desc:'Chica, para uno'},
  {subcat:'A Tu Gusto', nombre:'Tarta a tu gusto', desc:'Mitad y mitad, elegí dos sabores', especial:true}
];
const ADICIONAL_COMBINADA = 800;

function renderCategorias() {
  const el = document.getElementById('categorias-lista');
  el.innerHTML = '';
  CATEGORIAS.forEach((cat, idx) => {
    if (cat.especial) { renderCategoriaEspecial(cat, idx, el); return; }
    const lista = PRODUCTOS.filter(p => p.s === cat.subcat);
    const desde = Math.min(...lista.map(p => p.p));
    const img = imgFor(cat.subcat);

    const card = document.createElement('div');
    card.className = 'cat-card';
    card.id = 'catcard-' + idx;
    card.innerHTML = `
      <div class="cat-head" onclick="toggleCategoria(${idx})">
        <div class="cat-ph" style="background-image:url('${img}')"></div>
        <div class="cat-info">
          <div class="cat-nombre">${cat.nombre}</div>
          <div class="cat-desc">${cat.desc}</div>
          <div class="cat-precio">Desde ${fmt(desde)}</div>
        </div>
        <i class="cat-chev" id="chev-${idx}">›</i>
      </div>
      <div class="cat-sabores" id="sabores-${idx}">
        <div class="cat-sect-label">Sabores disponibles</div>
        <div class="grid" id="grid-${idx}"></div>
      </div>`;
    el.appendChild(card);

    const grid = card.querySelector('#grid-'+idx);
    lista.forEach(prod => {
      const d = document.createElement('div');
      d.className = 'card';
      d.innerHTML = `<div class="card-n">${prod.n.replace(/^(TARTA|MEDIA TARTA|TARTELLETA|TARTELETA)\s*/i,'')}</div>
        <div class="card-p">${fmt(prod.p)}</div>
        <div id="ctrl-${idFor(prod.n)}"><button class="card-btn" onclick="agregar('${prod.n.replace(/'/g,"\\'")}')">Agregar</button></div>`;
      grid.appendChild(d);
    });
  });
  // Todas las categorías arrancan cerradas para que se vean las 4 opciones de un vistazo
}

function renderCategoriaEspecial(cat, idx, el) {
  const sabores = PRODUCTOS.filter(p => p.s === 'Tarta Grande');
  const desdeEsp = Math.min(...sabores.map(p => p.p)) + ADICIONAL_COMBINADA;
  const img = IMG_TARTA_ENTERA;
  const opciones = sabores.map(p => `<option value="${p.n.replace(/"/g,'&quot;')}">${p.n.replace(/^TARTA\s*/i,'')} — ${fmt(p.p)}</option>`).join('');

  const card = document.createElement('div');
  card.className = 'cat-card';
  card.id = 'catcard-' + idx;
  card.innerHTML = `
    <div class="cat-head" onclick="toggleCategoria(${idx})">
      <div class="cat-ph" style="background-image:url('${img}')"></div>
      <div class="cat-info">
        <div class="cat-nombre">${cat.nombre}</div>
        <div class="cat-desc">${cat.desc}</div>
        <div class="cat-precio">Desde ${fmt(desdeEsp)}</div>
      </div>
      <i class="cat-chev" id="chev-${idx}">›</i>
    </div>
    <div class="cat-sabores" id="sabores-${idx}">
      <div class="cat-sect-label">Primera mitad</div>
      <select id="gusto1" onchange="actualizarCombinada()">${opciones}</select>
      <div class="cat-sect-label">Segunda mitad</div>
      <select id="gusto2" onchange="actualizarCombinada()">${opciones}</select>
      <div class="resumen-combinada" id="resumen-combinada"></div>
      <button class="card-btn" style="margin-top:10px" onclick="agregarCombinada()">Agregar al carrito</button>
    </div>`;
  el.appendChild(card);

  // Preseleccionar segundo select en el segundo sabor para que no arranque igual/igual
  setTimeout(() => {
    const sel2 = document.getElementById('gusto2');
    if (sel2 && sel2.options.length > 1) sel2.selectedIndex = 1;
    actualizarCombinada();
  }, 0);
}

function actualizarCombinada() {
  const s1 = document.getElementById('gusto1');
  const s2 = document.getElementById('gusto2');
  if (!s1 || !s2) return;
  const p1 = PRODUCTOS.find(p => p.n === s1.value);
  const p2 = PRODUCTOS.find(p => p.n === s2.value);
  if (!p1 || !p2) return;
  const mitad1 = p1.p / 2;
  const mitad2 = p2.p / 2;
  const total = Math.round(mitad1 + mitad2 + ADICIONAL_COMBINADA);
  document.getElementById('resumen-combinada').innerHTML = `
    <div class="resumen-row"><span>½ ${p1.n.replace(/^TARTA\s*/i,'')}</span><span>${fmt(Math.round(mitad1))}</span></div>
    <div class="resumen-row"><span>½ ${p2.n.replace(/^TARTA\s*/i,'')}</span><span>${fmt(Math.round(mitad2))}</span></div>
    <div class="resumen-row"><span>Adicional combinación</span><span>${fmt(ADICIONAL_COMBINADA)}</span></div>
    <div class="resumen-total"><span>Total</span><span>${fmt(total)}</span></div>`;
}

function agregarCombinada() {
  const s1 = document.getElementById('gusto1');
  const s2 = document.getElementById('gusto2');
  const p1 = PRODUCTOS.find(p => p.n === s1.value);
  const p2 = PRODUCTOS.find(p => p.n === s2.value);
  if (!p1 || !p2) return;
  const total = Math.round(p1.p/2 + p2.p/2 + ADICIONAL_COMBINADA);
  const nombreCombo = `TARTA A TU GUSTO: ½ ${p1.n.replace(/^TARTA\s*/i,'')} + ½ ${p2.n.replace(/^TARTA\s*/i,'')}`;
  // Cada combinación es un ítem único (no se agrupa con otras)
  carrito.push({n: nombreCombo, c:'Tartas', s:'A Tu Gusto', p: total, qty: 1});
  actualizarCartBar();
  toast('Agregado ✓');
}

function toggleCategoria(idx, forzarAbrir) {
  const sab = document.getElementById('sabores-'+idx);
  const chev = document.getElementById('chev-'+idx);
  const card = document.getElementById('catcard-'+idx);
  const abrir = forzarAbrir || !sab.classList.contains('vis');
  // Cerrar todas
  CATEGORIAS.forEach((_, i) => {
    document.getElementById('sabores-'+i).classList.remove('vis');
    document.getElementById('chev-'+i).classList.remove('rot');
    document.getElementById('catcard-'+i).classList.remove('abierta');
  });
  if (abrir) {
    sab.classList.add('vis');
    chev.classList.add('rot');
    card.classList.add('abierta');
  }
}

function idFor(nombre){ return nombre.replace(/[^a-zA-Z0-9]/g,''); }

function agregar(nombre) {
  const prod = PRODUCTOS.find(p => p.n === nombre);
  if (!prod) return;
  const existente = carrito.find(i => i.n === nombre);
  if (existente) existente.qty++;
  else carrito.push({...prod, qty:1});
  actualizarControl(nombre);
  actualizarCartBar();
  toast('Agregado ✓');
}

function cambiarQty(nombre, delta) {
  const item = carrito.find(i => i.n === nombre);
  if (!item) return;
  item.qty += delta;
  if (item.qty <= 0) carrito = carrito.filter(i => i.n !== nombre);
  actualizarControl(nombre);
  actualizarCartBar();
  if (document.getElementById('modal-carrito').classList.contains('vis')) renderCartItems();
}

function actualizarControl(nombre) {
  const el = document.getElementById('ctrl-'+idFor(nombre));
  if (!el) return;
  const item = carrito.find(i => i.n === nombre);
  if (!item) { el.innerHTML = `<button class="card-btn" onclick="agregar('${nombre.replace(/'/g,"\\'")}')">Agregar</button>`; return; }
  el.innerHTML = `<div class="qty-row">
    <button onclick="cambiarQty('${nombre.replace(/'/g,"\\'")}',-1)">−</button>
    <span>${item.qty}</span>
    <button onclick="cambiarQty('${nombre.replace(/'/g,"\\'")}',1)">+</button>
  </div>`;
}

function totalCarrito() { return carrito.reduce((s,i)=>s+i.p*i.qty,0); }
function cantCarrito() { return carrito.reduce((s,i)=>s+i.qty,0); }

function actualizarCartBar() {
  const bar = document.getElementById('cart-bar');
  const n = cantCarrito();
  document.getElementById('cart-count').textContent = n;
  document.getElementById('cart-total').textContent = fmt(totalCarrito());
  bar.classList.toggle('visible', n > 0);
}

// ─── CARRITO / CHECKOUT ────────────────────────────────────────
function abrirCarrito() {
  renderCartItems();
  document.getElementById('vista-carrito').style.display='block';
  document.getElementById('vista-checkout').style.display='none';
  document.getElementById('vista-exito').style.display='none';
  document.getElementById('modal-carrito').classList.add('vis');
}
function cerrarCarrito() { document.getElementById('modal-carrito').classList.remove('vis'); }

function renderCartItems() {
  const el = document.getElementById('cart-items');
  if (!carrito.length) { el.innerHTML = '<div class="empty-cart">Tu carrito está vacío.</div>'; }
  else {
    el.innerHTML = carrito.map(i => `
      <div class="cart-item">
        <div style="flex:1">
          <div class="cart-item-n">${i.n.replace(/^(TARTA|MEDIA TARTA|TARTELLETA|TARTELETA)\s*/i,'')}</div>
          <div class="cart-item-p">${fmt(i.p)} c/u</div>
        </div>
        <div class="qty-row">
          <button onclick="cambiarQty('${i.n.replace(/'/g,"\\'")}',-1)">−</button>
          <span>${i.qty}</span>
          <button onclick="cambiarQty('${i.n.replace(/'/g,"\\'")}',1)">+</button>
        </div>
      </div>`).join('');
  }
  document.getElementById('cart-total-modal').textContent = fmt(totalCarrito());
}

function irACheckout() {
  if (!carrito.length) { toast('Agregá al menos un producto'); return; }
  document.getElementById('vista-carrito').style.display='none';
  document.getElementById('vista-checkout').style.display='block';
  document.getElementById('aviso-envio').style.display = tipoPedido==='envio' ? 'block' : 'none';
}
function volverACarrito() {
  document.getElementById('vista-checkout').style.display='none';
  document.getElementById('vista-carrito').style.display='block';
}

function setTipo(tipo) {
  tipoPedido = tipo;
  document.getElementById('tipo-envio').classList.toggle('active', tipo==='envio');
  document.getElementById('tipo-retira').classList.toggle('active', tipo==='retira');
  document.getElementById('frow-dir').style.display = tipo==='retira' ? 'none' : 'block';
  document.getElementById('aviso-envio').style.display = tipo==='envio' ? 'block' : 'none';
}

function toggleDatosTransferencia() {
  const esTransferencia = document.getElementById('f-pago').value === 'Transferencia';
  document.getElementById('datos-transferencia').style.display = esTransferencia ? 'block' : 'none';
}

function copiarAlias() {
  navigator.clipboard.writeText(ALIAS_TRANSFERENCIA).then(() => {
    const btn = document.getElementById('btn-copiar-alias');
    const original = btn.textContent;
    btn.textContent = '✓ Copiado';
    setTimeout(() => { btn.textContent = original; }, 1500);
    toast('Alias copiado ✓');
  }).catch(() => toast('No se pudo copiar, copialo manualmente'));
}

async function confirmarPedido() {
  const nombre = document.getElementById('f-nombre').value.trim();
  const tel = document.getElementById('f-tel').value.trim();
  const dir = document.getElementById('f-dir').value.trim();
  let ok = true;
  [['f-nombre',nombre],['f-tel',tel]].forEach(([id,val])=>{
    const el = document.getElementById(id);
    if (!val) { el.classList.add('err'); ok=false; } else el.classList.remove('err');
  });
  if (tipoPedido==='envio') {
    const elDir = document.getElementById('f-dir');
    if (!dir) { elDir.classList.add('err'); ok=false; } else elDir.classList.remove('err');
  }
  if (!ok) { toast('Completá los datos requeridos'); return; }

  const btn = document.getElementById('btn-confirmar');
  btn.disabled = true; btn.textContent = 'Enviando...';

  const payload = {
    cliente_nombre: nombre,
    cliente_tel: tel,
    cliente_dir: tipoPedido==='retira' ? 'RETIRA EN LOCAL' : dir,
    horario_entrega: document.getElementById('f-horario').value.trim(),
    forma_pago: document.getElementById('f-pago').value,
    items: carrito.map(i => ({nombre:i.n, subcategoria:i.s, precio:i.p, qty:i.qty})),
    total: totalCarrito(),
    estado: 'pendiente',
    observaciones: (tipoPedido==='retira'?'RETIRA':'ENVIO') + ' | TIENDA WEB'
  };

  try {
    const res = await sbFetch('/rest/v1/pedidos', {
      method:'POST', prefer:'return=representation', body: JSON.stringify(payload)
    });
    const saved = Array.isArray(res) ? res[0] : res;
    pedidoConfirmado = {...payload, numero: saved?.numero};
    mostrarExito();
  } catch(e) {
    toast('Error al enviar: ' + e.message);
  } finally {
    btn.disabled = false; btn.textContent = '✓ Confirmar pedido';
  }
}

function mostrarExito() {
  document.getElementById('vista-checkout').style.display='none';
  document.getElementById('vista-exito').style.display='block';
  document.getElementById('exito-msg').textContent =
    `Pedido #${pedidoConfirmado.numero||'—'} guardado. Total: ${fmt(pedidoConfirmado.total)}.`;

  const instruccion = document.getElementById('exito-instruccion');
  if (pedidoConfirmado.forma_pago === 'Transferencia') {
    instruccion.innerHTML = `⚠️ Enviá tu pedido por WhatsApp y no te olvides de adjuntar la <b>foto del comprobante</b> de la transferencia en el mismo chat.`;
  } else {
    instruccion.textContent = '⚠️ Para confirmar tu pedido, avisanos por WhatsApp tocando el botón de abajo.';
  }

  // Intentar abrir WhatsApp automáticamente; si el navegador lo bloquea, el botón queda como respaldo
  setTimeout(() => { avisarWhatsApp(); }, 500);
}

function avisarWhatsApp() {
  const p = pedidoConfirmado;
  let msg = `🥧 *Pedido de tartas — Sorrento*\n`;
  msg += `Pedido #${p.numero||'—'}\n\n`;
  msg += `👤 ${p.cliente_nombre}\n📞 ${p.cliente_tel}\n`;
  if (p.cliente_dir !== 'RETIRA EN LOCAL') msg += `📍 ${p.cliente_dir}\n`;
  else msg += `🏠 Retira en el local\n`;
  if (p.horario_entrega) msg += `⏰ ${p.horario_entrega}\n`;
  if (p.forma_pago) msg += `💳 ${p.forma_pago}\n`;
  msg += `\n*Pedido:*\n`;
  p.items.forEach(i => { msg += `• ${i.nombre}${i.qty>1?' x'+i.qty:''} — ${fmt(i.precio*i.qty)}\n`; });
  msg += `\n💰 *Total: ${fmt(p.total)}*`;

  if (p.cliente_dir !== 'RETIRA EN LOCAL') {
    msg += `\n\n🛵 _El costo de envío no está incluido — lo confirmamos según tu zona._`;
  }

  if (p.forma_pago === 'Transferencia') {
    msg += `\n\n━━━━━━━━━━━━━━━━━━\n`;
    msg += `🏦 *DATOS PARA TRANSFERIR*\n`;
    msg += `Alias: *${ALIAS_TRANSFERENCIA}*\n`;
    msg += `Titular: *${TITULAR_TRANSFERENCIA}*\n`;
    msg += `━━━━━━━━━━━━━━━━━━\n`;
    msg += `📸 Por favor, enviame la foto del comprobante en este mismo chat para confirmar tu pedido ✅`;
  }

  window.open(`https://wa.me/${NUMERO_LOCAL}?text=${encodeURIComponent(msg)}`, '_blank');
}

function cerrarTodo() {
  carrito = [];
  document.querySelectorAll('[id^="ctrl-"]').forEach(el => {
    const nombre = PRODUCTOS.find(p => idFor(p.n) === el.id.replace('ctrl-',''))?.n;
    if (nombre) actualizarControl(nombre);
  });
  actualizarCartBar();
  ['f-nombre','f-tel','f-dir','f-horario'].forEach(id=>document.getElementById(id).value='');
  document.getElementById('f-pago').value='';
  document.getElementById('datos-transferencia').style.display='none';
  setTipo('envio');
  cerrarCarrito();
}

let toastTimer;
function toast(msg) {
  const el = document.getElementById('toast');
  el.textContent = msg; el.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=>el.classList.remove('show'), 1800);
}

// INIT
// INIT
(async () => {
  await cargarProductosTartas();
  renderCategorias();
})();
